import {
	type DefaultLink,
	type DefaultNode,
	ResponsiveSankey as Sankey,
	type SankeySvgProps,
} from "@harbor-charts/sankey";
import { Component, Element, Host, Method, Prop, h } from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { sankey } from "@harbor/chart-config/sankey";

const {
	getSankeyBaseConfig,
	getSankeyCategoricalConfig,
	getSankeyClickSelectionState,
	getSankeySelectionNodeIds,
	toggleSankeyItemClickSelection,
	updateSankeySelectionLabelState,
} = sankey;

import merge from "deepmerge";
import { browserDownloadCsv } from "../chart-board/board-util";
import { omitChartConfigKeys } from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	applyChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
import {
	convertSankeyDataToCSV,
	hideSankeyTooltip,
	showSankeyItemTooltip,
	showSankeyLegendTooltip,
} from "./chart-util";

type HbrTooltipFunctions = {
	itemTooltip?: (data, event, h) => string | object | false;
	legendTooltip?: (data, event, h) => string | object | false;
};

type SankeyChartConfig = Omit<
	Partial<SankeySvgProps<DefaultNode, DefaultLink>>,
	"nodeTooltip" | "linkTooltip"
> &
	HbrTooltipFunctions;

type ConfigWithNivoTooltips = SankeyChartConfig & {
	nodeTooltip?: unknown;
	linkTooltip?: unknown;
};

type SankeyLegendPopoverConfig = {
	popoverOptions?: ChartPopoverOptions;
};

type SankeySelectionState = ReturnType<typeof getSankeyClickSelectionState>;

const defaultI18n: { [key: string]: string } = {
	noData: "No data to display",
	noDataCategorical: "No matching results",
};

/**
 * @since 1.0.50
 * @status stable
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 */
@Component({
	tag: "hbr-sankey-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrSankeyChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;
	virtualElement: HTMLElement;
	selectedNodeIds: string[] = [];
	selectedSelectionState: SankeySelectionState | null = null;
	pendingItemClickSelection = false;
	restoreSelectionFrame: number | null = null;

	/** Chart configuration object. Refer to https://nivo.rocks/sankey */
	@Prop({ mutable: true }) config: SankeyChartConfig = {
		data: { nodes: [], links: [] },
	};
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";

	/** Chart loading flag */
	@Prop() loading = false;

	/** New Magnetic UX chart type */
	@Prop({ reflect: true }) categorical = false;

	/** i18n strings, supports noData and noDataCategorical */
	@Prop() i18n: { [key: string]: string } = {};

	@Prop()
	showHeader: "all" | "title" | "action" | "none" = "none";

	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: SankeyChartConfig,
		createElement: (tag: string, props, ...children) => React.ReactNode,
	) => ConfigWithNivoTooltips;

	/** Default popover props. Set `selfManaged` to let a categorical popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrSankeyChartElement;

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(filename = "Export.csv", customFunc?: (data) => void) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(convertSankeyDataToCSV(this.config.data), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;
	private warnedAboutNivoTooltips = false;

	private getLegendPopoverOptions() {
		return (
			this.config.legends?.[0] as unknown as
				| SankeyLegendPopoverConfig
				| undefined
		)?.popoverOptions;
	}

	private getPopoverOptions(override?: ChartPopoverOptions) {
		return resolveChartPopoverOptions(
			{
				distance: this.categorical ? -6 : 10,
				variant: "chart",
				placement: "top",
			},
			this.popoverOptions,
			this.categorical,
			override,
		);
	}

	private applyPopoverOptions(override?: ChartPopoverOptions) {
		const popoverOptions = this.getPopoverOptions(override);
		applyChartPopoverOptions(this.tooltipRef, popoverOptions);
		this.tooltipRef?.toggleAttribute(
			"data-sankey-width-expand",
			popoverOptions.widthExpand === true,
		);
	}

	private isPopoverSelfManaged(override?: ChartPopoverOptions) {
		return isChartPopoverSelfManaged(
			this.categorical,
			this.popoverOptions,
			override,
		);
	}

	private get clickSelectionEnabled() {
		return Boolean(
			(this.config as { enableClickSelection?: boolean })?.enableClickSelection,
		);
	}

	private get resolvedActiveLabelFontWeight() {
		const activeLabelFontWeight = (
			this.config as { activeLabelFontWeight?: number | string }
		)?.activeLabelFontWeight;

		if (typeof activeLabelFontWeight === "number") {
			return activeLabelFontWeight;
		}

		if (typeof activeLabelFontWeight === "string") {
			const parsedFontWeight = Number(activeLabelFontWeight);

			if (Number.isFinite(parsedFontWeight)) {
				return parsedFontWeight;
			}
		}

		return 700;
	}

	private get selectionVisualConfig() {
		const chartConfig = this.config as {
			linkHoverOpacity?: number;
			linkHoverOthersOpacity?: number;
			nodeHoverOpacity?: number;
			nodeHoverOthersOpacity?: number;
		};

		return {
			nodeHoverOpacity: chartConfig.nodeHoverOpacity ?? 1,
			nodeHoverOthersOpacity: chartConfig.nodeHoverOthersOpacity ?? 0.15,
			linkHoverOpacity: chartConfig.linkHoverOpacity ?? 0.6,
			linkHoverOthersOpacity: chartConfig.linkHoverOthersOpacity ?? 0.15,
		};
	}

	private syncSankeySelectionDataAttributes = () => {
		if (!this.chartRef) {
			return;
		}

		const data = this.config.data as
			| {
					nodes?: Array<{ id?: string }>;
					links?: Array<{
						source?: string | { id?: string };
						target?: string | { id?: string };
					}>;
			  }
			| undefined;

		const nodes = data?.nodes ?? [];
		const links = data?.links ?? [];
		const nodeElements = Array.from(
			this.chartRef.querySelectorAll("rect"),
		).slice(0, nodes.length);
		const linkElements = Array.from(this.chartRef.querySelectorAll("path"));

		nodeElements.forEach((element, index) => {
			const nodeId = nodes[index]?.id;

			if (typeof nodeId === "string") {
				element.setAttribute("data-sankey-node-id", nodeId);
			}
		});

		linkElements.forEach((element, index) => {
			const link = links[index];
			const sourceId =
				typeof link?.source === "string" ? link.source : link?.source?.id;
			const targetId =
				typeof link?.target === "string" ? link.target : link?.target?.id;

			if (typeof sourceId === "string") {
				element.setAttribute("data-sankey-source", sourceId);
			}

			if (typeof targetId === "string") {
				element.setAttribute("data-sankey-target", targetId);
			}
		});
	};

	private clearSelectionState = () => {
		if (this.restoreSelectionFrame !== null) {
			cancelAnimationFrame(this.restoreSelectionFrame);
			this.restoreSelectionFrame = null;
		}

		toggleSankeyItemClickSelection(
			this.chartRef,
			this.selectedSelectionState,
			false,
		);

		if (
			this.categorical &&
			(this.config as { enableActiveLabelEmphasis?: boolean })
				?.enableActiveLabelEmphasis
		) {
			updateSankeySelectionLabelState(
				this.chartRef,
				this.selectedNodeIds,
				false,
				this.resolvedActiveLabelFontWeight,
			);
		}

		this.selectedSelectionState = null;
		this.selectedNodeIds = [];
	};

	private applySelectionState = () => {
		if (!this.clickSelectionEnabled || !this.selectedSelectionState) {
			return;
		}

		toggleSankeyItemClickSelection(
			this.chartRef,
			this.selectedSelectionState,
			true,
			this.selectionVisualConfig,
		);

		if (
			this.categorical &&
			(this.config as { enableActiveLabelEmphasis?: boolean })
				?.enableActiveLabelEmphasis
		) {
			updateSankeySelectionLabelState(
				this.chartRef,
				this.selectedNodeIds,
				true,
				this.resolvedActiveLabelFontWeight,
			);
		}
	};

	private scheduleSelectionRestore = () => {
		if (!this.clickSelectionEnabled || !this.selectedSelectionState) {
			return;
		}

		if (this.restoreSelectionFrame !== null) {
			cancelAnimationFrame(this.restoreSelectionFrame);
		}

		this.restoreSelectionFrame = requestAnimationFrame(() => {
			this.restoreSelectionFrame = null;
			this.applySelectionState();
		});
	};

	private handleItemSelection = (data) => {
		if (!this.clickSelectionEnabled) {
			return;
		}

		this.pendingItemClickSelection = true;
		this.clearSelectionState();
		this.selectedSelectionState = getSankeyClickSelectionState(data);
		this.selectedNodeIds = getSankeySelectionNodeIds(data);
		this.applySelectionState();
	};

	private handleDocumentClick = () => {
		if (!this.clickSelectionEnabled) {
			return;
		}

		if (this.pendingItemClickSelection) {
			this.pendingItemClickSelection = false;
			return;
		}

		this.clearSelectionState();
	};

	componentDidLoad() {
		this.renderChart();
		retargetEvents(this.el.shadowRoot);
		document.addEventListener("click", this.handleDocumentClick);
	}

	componentShouldUpdate() {
		this.clearSelectionState();
		return this.renderChart();
	}

	disconnectedCallback() {
		document.removeEventListener("click", this.handleDocumentClick);
		this.clearSelectionState();
	}

	renderChart = async () => {
		const configWithNivoTooltips = this.config as ConfigWithNivoTooltips;
		if (
			!this.warnedAboutNivoTooltips &&
			(configWithNivoTooltips.nodeTooltip !== undefined ||
				configWithNivoTooltips.linkTooltip !== undefined)
		) {
			console.warn(
				"hbr-sankey-chart: config.nodeTooltip and config.linkTooltip are not supported. Use itemTooltip or legendTooltip instead.",
			);
			this.warnedAboutNivoTooltips = true;
		}
		const publicConfig = omitChartConfigKeys(configWithNivoTooltips, [
			"nodeTooltip",
			"linkTooltip",
		]) as SankeyChartConfig;
		const getConfig = this.categorical
			? getSankeyCategoricalConfig
			: getSankeyBaseConfig;
		const legendPopoverOptions = this.getLegendPopoverOptions();

		const baseConfig = getConfig(publicConfig, {
			itemsEventHandlers: {
				nodeTooltip: () => "",
				linkTooltip: () => "",
				onFocus: (data, event) => {
					this.applyPopoverOptions();
					showSankeyItemTooltip(
						data,
						event,
						this.tooltipRef,
						(
							this.config as SankeySvgProps<DefaultNode, DefaultLink> &
								HbrTooltipFunctions
						).itemTooltip,
						this.categorical,
					);
				},
				onBlur: () => {
					hideSankeyTooltip(this.tooltipRef);
					this.scheduleSelectionRestore();
				},
				onMouseEnter: (data, event) => {
					this.applyPopoverOptions();
					showSankeyItemTooltip(
						data,
						event,
						this.tooltipRef,
						(
							this.config as SankeySvgProps<DefaultNode, DefaultLink> &
								HbrTooltipFunctions
						).itemTooltip,
						this.categorical,
					);
				},
				onMouseLeave: () => {
					if (!this.isPopoverSelfManaged()) {
						hideSankeyTooltip(this.tooltipRef);
					}
					this.scheduleSelectionRestore();
				},
				onClick: (data) => {
					this.handleItemSelection(data);
				},
			},
			legendsEventHandlers: {
				onMouseEnter: (data, event) => {
					this.applyPopoverOptions(legendPopoverOptions);
					showSankeyLegendTooltip(
						data,
						event,
						this.tooltipRef,
						(
							this.config as SankeySvgProps<DefaultNode, DefaultLink> &
								HbrTooltipFunctions
						).legendTooltip,
					);
				},
				onMouseLeave: () => {
					if (!this.isPopoverSelfManaged(legendPopoverOptions)) {
						hideSankeyTooltip(this.tooltipRef);
					}
				},
				onFocus: (data, event) => {
					this.applyPopoverOptions(legendPopoverOptions);
					showSankeyLegendTooltip(
						data,
						event,
						this.tooltipRef,
						(
							this.config as SankeySvgProps<DefaultNode, DefaultLink> &
								HbrTooltipFunctions
						).legendTooltip,
					);
				},
				onBlur: () => {
					hideSankeyTooltip(this.tooltipRef);
				},
			},
		});

		const existingEventHandlers = {
			onMouseEnter: baseConfig.onMouseEnter,
			onMouseLeave: baseConfig.onMouseLeave,
			onClick: baseConfig.onClick,
			onblur: baseConfig.onBlur,
			onFocus: baseConfig.onFocus,
		};

		let fullConfig = merge(baseConfig as unknown, publicConfig, {
			customMerge: (key) => {
				if (key === "legends") {
					return (a, b) => {
						const ret =
							a.length > b.length
								? a.map((r, i) => ({ ...r, ...b[i] }))
								: b.map((r, i) => ({ ...r, ...a[i] }));
						return ret;
					};
				}
			},
		}) as unknown as ConfigWithNivoTooltips;

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as unknown as ConfigWithNivoTooltips;
		fullConfig = omitChartConfigKeys(fullConfig, [
			"nodeTooltip",
			"linkTooltip",
		]) as Partial<SankeySvgProps<DefaultNode, DefaultLink>>;

		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(
				fullConfig as SankeyChartConfig,
				React.createElement,
			);
		}
		fullConfig = {
			...fullConfig,
			nodeTooltip:
				(fullConfig as ConfigWithNivoTooltips).nodeTooltip ?? (() => ""),
			linkTooltip:
				(fullConfig as ConfigWithNivoTooltips).linkTooltip ?? (() => ""),
		};
		if (!this.chartRef.innerHTML.length) {
			const newRoot = createRoot(this.chartRef);
			newRoot.render(
				React.createElement(
					Sankey,
					fullConfig as SankeySvgProps<DefaultNode, DefaultLink>,
					null,
				),
			);
			this.contextRoot = newRoot;
		} else {
			this.contextRoot.render(
				React.createElement(
					Sankey,
					fullConfig as SankeySvgProps<DefaultNode, DefaultLink>,
					null,
				),
			);
		}

		requestAnimationFrame(() => {
			this.syncSankeySelectionDataAttributes();
			this.applySelectionState();
		});

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}
	};

	render() {
		const i18n = {
			...this.i18n,
			...defaultI18n,
		};
		const { config } = this;
		const layout = config.layout ? config.layout : "vertical";
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const popoverOptions = resolveChartPopoverOptions(
			{ distance: this.categorical ? -6 : 10, variant: "chart" },
			this.popoverOptions,
			this.categorical,
		);

		return (
			<Host class={this.categorical ? "categorical" : ""}>
				{!Object.keys(config.data || {}).length && this.categorical && (
					<div slot="header" part="header" class="chart-sankey__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
				)}
				<hbr-chart-board
					ref={(el) => {
						this.boardRef = el;
					}}
					type={this.categorical ? "categorical-sankey" : null}
					description={this.categorical ? i18n.noDataCategorical : i18n.noData}
					isLoading={this.loading}
					isEmpty={!Object.keys(config.data || {}).length}
					style={{ width: this.width, height: this.height }}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						data-sankey-width-expand={
							popoverOptions.widthExpand === true ? "true" : undefined
						}
						style={
							this.categorical
								? { "--text-color": "var(--base-text-default)" }
								: undefined
						}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					{(Object.keys(config.data || {}).length || !this.categorical) && (
						<div slot="header" part="header" class="chart-sankey__header">
							<slot name="header">
								<div>
									<slot name="header-title" />
								</div>
								<div>
									<slot name="header-action" />
								</div>
							</slot>
						</div>
					)}
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class={`--hbr-chart --sankey-chart --sankey-${layout} ${
							this.categorical ? "--categorical" : ""
						}`}
						part="chart"
					/>
					<div slot="footer">
						<slot name="footer" />
					</div>
					<div slot="loading-state">
						<slot name="loading-state" />
					</div>
					<div slot="empty-state">
						<slot name="empty-state" />
					</div>
				</hbr-chart-board>
			</Host>
		);
	}
}
